CREATE OR REPLACE FUNCTION public.protect_lead_immutable_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.is_org_admin() THEN
        IF NEW.organization_id <> OLD.organization_id THEN
            RAISE EXCEPTION 'Agents are strictly forbidden from modifying lead organization boundary.';
        END IF;
        IF NEW.created_by IS DISTINCT FROM OLD.created_by THEN
            RAISE EXCEPTION 'Agents are strictly forbidden from modifying lead creator.';
        END IF;
        IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to THEN
            IF NEW.assigned_to IS NOT NULL AND NEW.assigned_to <> public.current_profile_id() THEN
                RAISE EXCEPTION 'Agents are not permitted to reassign leads to other sales agents.';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_profile_immutable_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.is_org_admin() THEN
        IF NEW.role <> OLD.role THEN
            RAISE EXCEPTION 'Agents are strictly forbidden from altering user roles.';
        END IF;
        IF NEW.organization_id <> OLD.organization_id THEN
            RAISE EXCEPTION 'Users cannot alter their organization assignment.';
        END IF;
        IF NEW.status <> OLD.status THEN
            RAISE EXCEPTION 'Agents cannot alter user activation status.';
        END IF;
        IF NEW.auth_user_id <> OLD.auth_user_id THEN
            RAISE EXCEPTION 'Authentication identity mapping cannot be changed.';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$
